//   Wikipedia – https://en.wikipedia.org/wiki/List_of_tz_database_time_zones
ZoneId shanghaiTz = ZoneId.of("Asia/Shanghai");
ZonedDateTime start = ZonedDateTime.of(2025, 1, 1, 0, 0, 0, 0, shanghaiTz);

